// Never automatically replace invalid or missing local data with an empty seed if a database mirror exists.
let migrationPending=true;
async function initDB(){try{let prior=await dbOp('state','readonly',o=>o.get('latest'));dbReady=true;if(prior&&validPro(prior)&&(prior.pro?.schema||1)<3){try{await dbOp('snapshots','readwrite',o=>o.put({id:uid(),date:Date.now(),payload:clone(prior)}));}catch{mirrorError=true;}}if(prior&&validPro(prior)&&(storageError||!hadLocalData||(prior.pro?.savedAt||0)>(state.pro.savedAt||0))){state=migrate(prior);if(typeof migrate3==='function')migrate3(state);if(state.pro.guide?.running){state.pro.guide.running=false;state.pro.guide.remaining=Math.max(1,state.pro.guide.remaining||1);}storageError=false;protectUnreadable=false;save();render();toast('Recovered local database snapshot');}else if(!protectUnreadable){save();await dbOp('state','readwrite',o=>o.put(clone(state),'latest'));}if(page==='settings')render();}catch{mirrorError=true;if(!protectUnreadable)old.save();}finally{migrationPending=false;}}
