function regionSummary(g,days=7){const data=flattened(records(days)).filter(s=>s.region===g),all=flattened().filter(s=>s.region===g).sort((a,b)=>b.date.localeCompare(a.date)||b.finished.localeCompare(a.finished)),last=all[0];let hours=null;if(last){const timestamp=last.finished&&dateLocal(new Date(last.finished))===last.date?Date.parse(last.finished):Date.parse(last.date+'T12:00:00');hours=Math.max(0,(Date.now()-timestamp)/3600000);}return {sets:data.length,goal:Number(state.pro.goals[g])||0,last:last?.date||'',hours,recovery:hours==null?null:Math.min(100,Math.round(hours/state.pro.recoveryHours*100)),secondary:flattened(records(days)).filter(s=>s.secondary.includes(g)).length};}
function progression(e){const matches=flattened().filter(s=>s.exerciseKey===(e.exerciseKey||e.id)&&s.weight!=null&&s.type!=='Warm-up').sort((a,b)=>b.date.localeCompare(a.date)||b.finished.localeCompare(a.finished));if(!matches.length)return 'No recorded resistance yet. Log actual weights and effort to establish a baseline.';const latest=matches.filter(s=>s.sessionId===matches[0].sessionId),p=e.sets,base=matches[0].weight;const rpes=latest.filter(s=>s.rpe!=null);if(!rpes.length||rpes.length!==latest.length)return `Last load: ${weightLabel(base)}. Record RPE for each working set before considering an increase.`;if(rpes.some(s=>s.rpe>=9))return 'High effort last session. Repeat the load or reduce it if technique or comfort deteriorated.';const met=p.length>0&&latest.length>=p.length&&p.every((target,i)=>{const s=latest[i];return s&&((e.mode==='time'||e.mode==='both')?target.seconds==null||s.seconds>=target.seconds:true)&&((e.mode==='reps'||e.mode==='both')?target.reps==null||s.reps>=target.reps:true);});const sessions=[...new Set(matches.map(s=>s.sessionId))];const two=sessions.length>=2&&sessions.slice(0,2).every(id=>{const ss=matches.filter(s=>s.sessionId===id);return ss.length>=p.length&&ss.every(s=>s.weight===base&&s.rpe!=null&&s.rpe<=7)&&p.every((t,i)=>(t.reps==null||ss[i]?.reps>=t.reps)&&(t.seconds==null||ss[i]?.seconds>=t.seconds));});if(met&&two){const next=profile().weights.filter(w=>w>base).sort((a,b)=>a-b)[0];if(next&&next/base<=1.15&&meta(e).equipment==='Dumbbells')return `Optional next target: ${weightLabel(next)}. Try it only with good form; stop or reduce if needed.`;return `Targets met twice at ${weightLabel(base)}. Progress with an extra rep or a small available increment (if appropriate), not a large jump.`;}return `Repeat ${weightLabel(base)} and meet all targets at manageable effort across two sessions before increasing.`;}
