function plateauText(data,logs){const dates=[...logs].reverse().map(w=>{const v=data.filter(s=>s.sessionId===w.id&&s.weight!=null).map(s=>s.weight);return v.length?Math.max(...v):null;}).filter(v=>v!=null);if(dates.length<3)return 'At least three logged sessions with resistance are needed to assess a load trend.';const tail=dates.slice(-3);return tail.every(v=>v===tail[0])?'Recorded peak load is unchanged across the last three sessions. Reps, interval quality and effort may still be improving; this is not a physiological plateau.':tail[2]>tail[0]?'Recorded peak load increased across the latest three sessions.':'Recorded peak load varied across the latest three sessions.';}
function analyticsPage(){const logs=records(rangeDays),all=flattened(logs),allHistory=flattened(),keys=[...new Map(allHistory.map(s=>[s.exerciseKey,s.name])).entries()].sort((a,b)=>a[1].localeCompare(b[1]));if(!keys.some(k=>k[0]===analyticsKey))analyticsKey=keys[0]?.[0]||'';const data=all.filter(s=>s.exerciseKey===analyticsKey);const val=s=>analyticsMetric==='weight'?s.weight==null?null:displayWeight(s.weight):analyticsMetric==='seconds'?s.seconds:analyticsMetric==='reps'?s.reps:analyticsMetric==='volume'?s.weight!=null&&s.reps!=null?displayWeight(s.weight)*s.reps:null:s.weight!=null&&s.reps>=2&&s.reps<=10&&s.mode!=='time'?displayWeight(s.weight)*(1+s.reps/30):null;const vals=data.map(val).filter(v=>v!=null),chartData=[...logs].reverse().flatMap(w=>{let v=data.filter(s=>s.sessionId===w.id).map(val).filter(v=>v!=null);return v.length?[{label:fmtDate(w.date),value:Math.max(...v)}]:[]}).slice(-15);const suffix=['weight','volume','e1rm'].includes(analyticsMetric)?' '+units():analyticsMetric==='seconds'?' s':' reps';const previous=analyticsKey?allHistory.filter(s=>s.exerciseKey===analyticsKey).map(val).filter(v=>v!=null):[];const rpes=all.filter(s=>s.rpe!=null);return `<div class="eyebrow">Training intelligence</div><div class="row spread"><h1>Progress</h1>${proBtn('report','PDF report')}</div><section class="panel"><label>Date range<select id="rangeDays">${[[7,'7 days'],[30,'30 days'],[90,'90 days'],[180,'180 days'],[365,'365 days'],[0,'All time']].map(([v,n])=>`<option value="${v}" ${rangeDays===v?'selected':''}>${n}</option>`).join('')}</select></label></section><div class="stats">${stat(logs.length,'Workouts')}${stat(all.length,'Completed sets')}${stat(minutes(sum(logs,workSeconds)),'Timed work')}${stat(fmt(displayWeight(sum(logs,volume)))+' '+units(),'Logged rep volume')}${stat(rpes.length?fmt(sum(rpes,s=>s.rpe)/rpes.length):'—','Mean RPE')}${stat(new Set(all.map(s=>s.exerciseKey)).size,'Exercises')}</div><section class="panel"><h2>Workout consistency</h2>${chart(weeklyChart())}<small>Always shows last eight calendar weeks.</small></section><section class="panel"><h2>Exercise progression</h2><div class="fields"><label>Exercise<select id="analyticsKey">${keys.map(([k,n])=>`<option value="${esc(k)}" ${analyticsKey===k?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label>Metric<select id="analyticsMetric">${options(['weight','reps','seconds','volume','e1rm'],analyticsMetric)}</select></label></div><div class="stats">${stat(vals.length?fmt(Math.max(...vals))+suffix:'—','Best in range')}${stat(previous.length?fmt(Math.max(...previous))+suffix:'—','All-time best')}</div>${chart(chartData,suffix)}<small>Best completed set per session. Volume is entered load × reps, not total tonnage if you enter per-dumbbell load. e1RM is an Epley estimate for rep sets of 2–10 reps, not a max test. Unknown values are excluded.</small><p class="coach">${esc(plateauText(data,logs))}</p></section>${musclePanel()}<section class="panel"><h2>Primary muscle distribution</h2>${REGIONS.map(g=>{const n=all.filter(s=>s.region===g).length;return n?`<div class="row spread"><b>${esc(g)}</b><small>${n} sets</small></div><div class="bar"><span style="width:${100*n/Math.max(1,all.length)}%"></span></div>`:'';}).join('')||'<p>No sets in range.</p>'}</section>`;}
// Guided timed circuits: time uses a wall-clock deadline. Leaving the tab pauses
// the timer so the app never silently marks exercises completed while away.
let guideHandle=null, lastGuideShown='', guideVideo=false;
function guideItems(){return state.active?.exercises.flatMap((e,i)=>e.sets.map((s,j)=>({e,s,i,j})))||[];}
function currentGuideItem(){const g=state.pro.guide;if(!g)return null;return guideItems().find(x=>x.e.id===g.exerciseId&&x.j===g.setIndex)||null;}
function chooseGuideItem(x){if(!x){state.pro.guide={sessionId:state.active?.id,phase:'done',remaining:0,running:false};return;}state.pro.guide={sessionId:state.active.id,exerciseId:x.e.id,setIndex:x.j,phase:'ready',remaining:x.s.seconds||0,running:false,deadline:0};}
function ensureGuide(){let g=state.pro.guide;if(!state.active)return false;if(!g||g.sessionId!==state.active.id||(!currentGuideItem()&&g.phase!=='done')||(g.phase==='done'&&guideItems().some(x=>!x.s.done))){chooseGuideItem(guideItems().find(x=>!x.s.done));save();}return true;}
function guideRemaining(g){return g.running?Math.max(0,Math.ceil((g.deadline-Date.now())/1000)):Math.max(0,g.remaining||0);}
function guidePause(){const g=state.pro.guide;if(g?.running){g.remaining=guideRemaining(g);g.running=false;save();}}
function guideStart(){const g=state.pro.guide,x=currentGuideItem();if(!g||!x||g.phase==='done')return;if(g.phase==='ready'){if(!x.s.seconds||x.e.mode==='reps'){g.phase='manual';g.remaining=0;save();return refreshGuide();}g.phase='work';g.remaining=x.s.seconds;g.planned=x.s.seconds;}if(!['work','rest'].includes(g.phase))return;g.running=true;g.deadline=Date.now()+g.remaining*1000;save();refreshGuide();}
function markGuide(){const g=state.pro.guide,x=currentGuideItem();if(!g||!x)return;x.s.done=true;if(g.phase==='work'&&g.planned!=null)x.s.seconds=g.planned;g.phase='rest';g.remaining=x.e.rest||0;g.running=g.remaining>0;g.deadline=Date.now()+g.remaining*1000;save();if(!g.remaining)advanceGuide();else refreshGuide();}
function advanceGuide(){const x=currentGuideItem(),list=guideItems();const at=x?list.findIndex(y=>y.e.id===x.e.id&&y.j===x.j):-1;const next=list.slice(at+1).find(y=>!y.s.done)||list.find(y=>!y.s.done);chooseGuideItem(next);save();refreshGuide();if(next&&next.s.seconds>0&&next.e.mode!=='reps')guideStart();}
function guideSkip(){const x=currentGuideItem(),list=guideItems(),i=x?list.findIndex(y=>y.e.id===x.e.id&&y.j===x.j):-1;const next=list.slice(i+1).find(y=>!y.s.done);if(next){chooseGuideItem(next);save();refreshGuide();}else{guidePause();toast('No later sets. Return to the session to finish or review skipped sets.');nav('session');}}
function guideTick(){const g=state.pro.guide;if(page!=='guide'||!g||!g.running)return;const t=guideRemaining(g);const node=$('#guideClock');if(node)node.textContent=`${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;if(t===0){g.running=false;g.remaining=0;try{navigator.vibrate?.([120,60,120]);}catch{}if(g.phase==='work'){markGuide();toast('Work interval complete');}else if(g.phase==='rest'){advanceGuide();toast('Next set');}}}
function youtubeId(url){try{const u=new URL(url);if(u.hostname==='youtu.be')return /^[\w-]{11}$/.test(u.pathname.slice(1))?u.pathname.slice(1):'';if(['www.youtube.com','youtube.com','m.youtube.com','www.youtube-nocookie.com'].includes(u.hostname)){const id=u.searchParams.get('v')||u.pathname.split('/')[2];return /^[\w-]{11}$/.test(id||'')?id:'';}}catch{}return '';}
function stampSeconds(stamp){return /^\d+(?::\d{1,2}){1,2}$/.test(stamp||'')?stamp.split(':').reduce((a,b)=>a*60+Number(b),0):0;}
function videoSource(){const r=routineBy(state.active?.routineId);return {video:r?.video||'',id:youtubeId(r?.video),stamp:currentGuideItem()?.e.stamp||''};}
function guideContent(){const g=state.pro.guide,x=currentGuideItem(),w=state.active;if(!g||!w)return '<p>No session.</p>';const done=completed(w).length,total=countSets(w);if(g.phase==='done'||!x)return `<div class="hero"><h2>Session intervals complete</h2><p>${done}/${total} sets marked complete. Review weights, repetitions and effort before saving.</p>${proBtn('review','Review & save','','primary')}</div>`;const time=guideRemaining(g),phase=g.phase;return `<div class="row spread"><span class="tag">${done} / ${total} sets complete</span><span class="tag">${esc(phase.toUpperCase())}</span></div><div class="bar"><span style="width:${total?100*done/total:0}%"></span></div><section class="hero guide-card"><div class="eyebrow">Exercise ${x.i+1} of ${w.exercises.length} · set ${x.j+1} / ${x.e.sets.length}</div><h2>${esc(x.e.name)}</h2><small>${esc(meta(x.e).region)} · ${esc(meta(x.e).equipment)}</small><div class="timer-ring"><strong id="guideClock">${Math.floor(time/60)}:${String(time%60).padStart(2,'0')}</strong><span>${phase==='rest'?'REST':phase==='manual'?'REPETITIONS':phase==='ready'?'READY':'WORK'}</span></div><div class="fields"><label>Weight (${units()})<input data-guide="weight" type="number" min="0" step="any" value="${esc(displayWeight(x.s.weight))}"></label><label>Actual reps (optional)<input data-guide="reps" type="number" min="0" step="1" value="${esc(x.s.reps)}"></label><label>RPE (optional)<select data-guide="rpe"><option value="">—</option>${options(Array.from({length:10},(_,i)=>String(i+1)),String(x.s.rpe??''))}</select></label></div><div class="row center">${phase==='ready'?proBtn('guideStart',x.s.seconds&&x.e.mode!=='reps'?'Start interval':'Start set','','primary'):phase==='manual'?proBtn('guideComplete','Mark set complete','','primary'):g.running?proBtn('guidePause','Pause','','primary'):proBtn('guideStart','Resume','','primary')}${phase==='rest'?proBtn('guideNext','Skip rest'):phase==='work'?proBtn('guideComplete','Finish interval early'):''}${phase!=='rest'?proBtn('guideSkip','Skip set'):''}</div><small>Planned work ${x.s.seconds??'—'}s · rest ${x.e.rest}s. Timed sets auto-complete only while this screen is active.</small></section><div class="row">${proBtn('review','Review/edit sets')}${videoSource().id?proBtn('seekVideo','Load this video chapter'):''}${timestampLink(routineBy(w.routineId),x.e)}</div>`;}
function guidePage(){if(!ensureGuide())return '<h1>No active workout</h1>';const v=videoSource();return `<div class="eyebrow">Guided training</div><div class="row spread"><h1>${esc(state.active.name)}</h1>${proBtn('review','Exit guide')}</div>${v.video?`<section class="panel video-panel"><div class="row spread"><h2>Workout video</h2>${link(v.video,'Open on YouTube ↗')}</div><div id="videoHost">${v.id?'<p>Load the embedded player to follow along. YouTube requires an internet connection and may block embedding.</p>'+proBtn('loadVideo','Load video'):''}</div><small>Video playback is independent of the interval timer; align it manually using chapter links.</small></section>`:''}<div id="guideContent">${guideContent()}</div>`;}
function refreshGuide(){if(page==='guide'&&$('#guideContent'))$('#guideContent').innerHTML=guideContent();}
function loadVideo(){const v=videoSource();if(!v.id||!$('#videoHost'))return;$('#videoHost').innerHTML=`<iframe title="Workout video player" src="https://www.youtube-nocookie.com/embed/${v.id}?start=${stampSeconds(v.stamp)}&rel=0" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;}
// Re-opened timers pause rather than record sets while the app was closed.
if(state.pro.guide?.running){state.pro.guide.remaining=Math.max(1,state.pro.guide.remaining||1);state.pro.guide.running=false;}
setInterval(guideTick,250);
document.addEventListener('visibilitychange',()=>{if(document.hidden){guidePause();}else if(page==='guide')refreshGuide();});
const baseNav=nav;nav=function(p){if(page==='guide'&&p!=='guide')guidePause();return baseNav(p);};
// Standalone rest/work timers also persist across page refreshes.
function rememberTimer(){state.pro.restTimer=timer?clone(timer):null;save();}
setTimer=function(seconds,label){old.setTimer(seconds,label);rememberTimer();};
stopTimer=function(){old.stopTimer();rememberTimer();};
updateTimer=function(){const before=timer?.finished;old.updateTimer();if(timer&&timer.finished&&!before)rememberTimer();};
if(state.pro.restTimer){timer=clone(state.pro.restTimer);if(!timer.paused&&!timer.finished){timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.paused=true;}tickHandle=setInterval(updateTimer,250);}
const BODY_KINDS=['Body weight','Body fat','Waist','Hips','Shoulders','Chest','Upper arm','Thigh','Calf','Neck'];
const bodyUnits=k=>k==='Body weight'?['lb','kg']:k==='Body fat'?['%']:['in','cm'];
function normalizedMeasurement(m){return m.kind==='Body weight'?m.unit==='kg'?m.value*2.2046226218:m.unit==='lb'?m.value:null:m.kind==='Body fat'?m.unit==='%'?m.value:null:m.unit==='cm'?m.value/2.54:m.unit==='in'?m.value:null;}
function bodySeries(k){return state.measurements.filter(m=>m.kind===k&&normalizedMeasurement(m)!=null).sort((a,b)=>a.date.localeCompare(b.date));}
function latestMeasure(k){return bodySeries(k).at(-1);}
function bodyRatios(){let dates=[...new Set(state.measurements.map(m=>m.date))].sort();const paired=(a,b)=>dates.flatMap(date=>{let m=bodySeries(a).filter(m=>m.date===date).at(-1),n=bodySeries(b).filter(m=>m.date===date).at(-1);return m&&n&&normalizedMeasurement(n)>0?[{date,value:normalizedMeasurement(m)/normalizedMeasurement(n)}]:[];});return {waistHip:paired('Waist','Hips'),shoulderWaist:paired('Shoulders','Waist'),lean:dates.flatMap(date=>{let w=bodySeries('Body weight').filter(m=>m.date===date).at(-1),f=bodySeries('Body fat').filter(m=>m.date===date).at(-1);return w&&f&&f.value>=0&&f.value<=100?[{date,value:normalizedMeasurement(w)*(1-f.value/100)}]:[];})};}
function photoMarkup(){if(photoLoading)return '<p>Loading private photo gallery…</p>';let p=photoCache.filter(x=>photoView==='All'||x.view===photoView).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="row spread"><label>Filter by view<select id="photoView">${options(['All','Front','Side','Back'],photoView)}</select></label>${p.length?proBtn('photoCompare','Compare oldest & newest'):''}</div><div id="photoCompare"></div><div class="photo-grid">${p.map(x=>`<article class="photo-card"><img src="${esc(x.url)}" alt="${esc(x.view)} progress photo from ${esc(x.date)}" loading="lazy"><div class="row spread"><small>${esc(x.view)} · ${fmtDate(x.date)}</small>${proBtn('deletePhoto','Delete',`data-id="${esc(x.id)}"`,'danger')}</div></article>`).join('')}</div>${p.length?'':'<p>No photos for this view.</p>'}`;}
async function refreshPhotos(){if(photoLoading)return;photoLoading=true;try{let all=await dbOp('photos','readonly',o=>o.getAll());photoUrls.forEach(URL.revokeObjectURL);photoUrls=[];photoCache=all.map(p=>{const url=URL.createObjectURL(p.blob);photoUrls.push(url);return {...p,url};});}catch{mirrorError=true;}finally{photoLoading=false;if(page==='body'&&$('#photoGallery'))$('#photoGallery').innerHTML=photoMarkup();}}
async function compressPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>25*1024*1024)throw Error('Choose a JPEG, PNG or WebP photo under 25 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const factor=Math.min(1,1400/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*factor));canvas.height=Math.max(1,Math.round(img.height*factor));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Image conversion failed')),'image/jpeg',.82));}finally{URL.revokeObjectURL(url);}}
function bodyPage(){const ratios=bodyRatios(),latest=k=>{const m=latestMeasure(k);return m?fmt(m.value)+' '+m.unit:'—';},rs=a=>a.length?fmt(a.at(-1).value*100)/100:'—',ratioDisplay=a=>a.length?a.at(-1).value.toFixed(2):'—',data=bodySeries(bodyMetric),unit=bodyMetric==='Body weight'?'lb':bodyMetric==='Body fat'?'%':'in';return `<div class="eyebrow">Private transformation journal</div><h1>Body composition</h1><p>Measurements are optional. Trends depend on consistent measuring conditions; body fat and lean mass are estimates.</p><div class="stats">${stat(latest('Body weight'),'Body weight')}${stat(latest('Body fat'),'Body fat')}${stat(ratios.lean.length?fmt(ratios.lean.at(-1).value)+' lb':'—','Estimated lean mass')}${stat(ratioDisplay(ratios.waistHip),'Waist / hip')}${stat(ratioDisplay(ratios.shoulderWaist),'Shoulder / waist')}</div><section class="panel"><h2>Log a measurement</h2><form id="bodyForm"><div class="fields"><label>Date<input type="date" name="date" value="${dateLocal()}" required></label><label>Metric<select name="kind" id="bodyKind">${options(BODY_KINDS,bodyMetric)}</select></label><label>Value<input type="number" name="value" min="0.01" step="any" required></label><label>Unit<select name="unit" id="bodyUnit">${options(bodyUnits(bodyMetric),bodyUnits(bodyMetric)[0])}</select></label></div><button type="submit" class="primary">Save measurement</button></form></section><section class="panel"><h2>Measurement trend</h2><label>Metric<select id="bodyMetric">${options(BODY_KINDS,bodyMetric)}</select></label>${chart(data.slice(-15).map(m=>({label:fmtDate(m.date),value:normalizedMeasurement(m)})),' '+unit)}<small>Latest 15 entries · converted to ${unit} for consistent comparison.</small></section><section class="panel"><h2>Physique ratios</h2><p>Ratios are calculated only when both measurements are recorded on the same date. No target or ideal ratio is assumed.</p><h3>Waist-to-hip</h3>${chart(ratios.waistHip.slice(-12).map(m=>({label:fmtDate(m.date),value:Math.round(m.value*100)/100})))}<h3>Shoulder-to-waist</h3>${chart(ratios.shoulderWaist.slice(-12).map(m=>({label:fmtDate(m.date),value:Math.round(m.value*100)/100})))}</section><section class="panel"><h2>Private progress photos</h2><p>Photos are resized and stored in this browser's IndexedDB, never uploaded by cloud sync. They are not encrypted at rest; anyone with access to this browser profile may access them.</p><form id="photoForm"><div class="fields"><label>Date<input type="date" name="date" value="${dateLocal()}" required></label><label>View<select name="view">${options(['Front','Side','Back'],'Front')}</select></label></div><label>Photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><button type="submit" class="primary">Save locally</button></form><div id="photoGallery">${photoMarkup()}</div></section><section class="panel"><h2>Measurement history</h2>${[...state.measurements].sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<div class="exercise row spread"><div><strong>${esc(m.kind)} · ${fmt(m.value)} ${esc(m.unit)}</strong><br><small>${fmtDate(m.date)}</small></div><div class="row">${proBtn('editMeasurement','Edit',`data-id="${esc(m.id)}"`)}${btn('deleteMeasurement','Delete',`data-id="${esc(m.id)}"`,'danger')}</div></div>`).join('')||'<p>No measurements yet.</p>'}</section>`;}
// Backups include a v1-compatible workout payload plus optional local photos.
function blobData(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob);});}
async function exportFull(includePhotos){try{const payload=clone(state);payload.pro.guide=payload.pro.guide?{...payload.pro.guide,running:false,remaining:guideRemaining(payload.pro.guide)}:null;payload.pro.restTimer=null;if(includePhotos){const list=await dbOp('photos','readonly',o=>o.getAll());payload.photoBackup=await Promise.all(list.map(async p=>({id:p.id,date:p.date,view:p.view,data:await blobData(p.blob)})));}download('fitlog-v2-'+dateLocal()+(includePhotos?'-with-photos':'')+'.json',JSON.stringify(payload,null,2),'application/json');toast('Backup exported');}catch(e){toast('Export failed: '+e.message);}}
function validPro(x){if(!old.validate(x))return false;if(!x.pro)return true;let p=x.pro;if(typeof p!=='object'||Array.isArray(p))return false;if(p.profiles!=null&&(!Array.isArray(p.profiles)||!p.profiles.length||!p.profiles.every(q=>q&&typeof q.id==='string'&&typeof q.name==='string'&&Array.isArray(q.equipment)&&q.equipment.every(e=>EQUIPMENT.includes(e))&&Array.isArray(q.weights)&&q.weights.every(w=>Number.isFinite(w)&&w>0))))return false;if(p.goals!=null&&(typeof p.goals!=='object'||Object.values(p.goals).some(v=>!Number.isFinite(v)||v<0||v>50)))return false;if(p.readiness!=null&&(!Array.isArray(p.readiness)||p.readiness.some(r=>!r||typeof r.date!=='string'||['sleep','energy','soreness','stress'].some(k=>!Number.isInteger(r[k])||r[k]<1||r[k]>5))))return false;for(const w of [...x.routines,...x.history,...(x.active?[x.active]:[])])for(const e of w.exercises){if(e.secondary!=null&&(!Array.isArray(e.secondary)||e.secondary.some(v=>typeof v!=='string')))return false;if(e.region!=null&&typeof e.region!=='string')return false;if(e.exerciseKey!=null&&typeof e.exerciseKey!=='string')return false;}return true;}
function parsePhotos(x){if(x.photoBackup==null)return null;if(!Array.isArray(x.photoBackup)||x.photoBackup.length>1000)throw Error('Invalid photo backup');return x.photoBackup.map(p=>{if(!p||typeof p.id!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||!['Front','Side','Back'].includes(p.view)||typeof p.data!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(p.data)||p.data.length>5000000)throw Error('Invalid photo entry');let bytes=Uint8Array.from(atob(p.data.split(',')[1]),c=>c.charCodeAt(0));if(bytes[0]!==255||bytes[1]!==216)throw Error('Invalid JPEG data');return {id:p.id,date:p.date,view:p.view,blob:new Blob([bytes],{type:'image/jpeg'})};});}
async function restoreData(x,includePhotos=true){if(!validPro(x))throw Error('Invalid FitLog backup');const images=includePhotos?parsePhotos(x):null;const cleaned=clone(x);delete cleaned.photoBackup;cleaned.pro=cleaned.pro||{};cleaned.pro.guide=null;cleaned.pro.restTimer=null;const migrated=migrate(cleaned);if(images){const d=await database();await new Promise((resolve,reject)=>{const t=d.transaction(['photos','state'],'readwrite'),p=t.objectStore('photos');p.clear();images.forEach(i=>p.put(i));t.objectStore('state').put(migrated,'latest');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});}state=migrated;storageError=false;protectUnreadable=false;stopTimer();save();await refreshPhotos();nav('home');}
$('#importFile').addEventListener('change',async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>120*1024*1024)throw Error('Backup exceeds 120 MB');const x=JSON.parse(await f.text());if(!validPro(x))throw Error('Invalid FitLog backup');parsePhotos(x);if(confirm('Replace workouts, routines and settings with this backup? '+(x.photoBackup?'Included photos will replace your local gallery.':'Existing local photos will be kept.')+' Export first if needed.')){await restoreData(x);toast('Backup imported');}}catch(e){toast('Import failed: '+e.message);}finally{ev.target.value='';}});
function reportPage(){const logs=records(rangeDays),a=flattened(logs),r=bodyRatios();return `<div class="row no-print">${proBtn('backProgress','← Progress')}${proBtn('print','Print / Save as PDF','','primary')}</div><article id="printReport"><div class="eyebrow">FitLog 2.0 · Personal training report</div><h1>Workout progress report</h1><p>Generated ${fmtDate(dateLocal())} · ${rangeDays?`Last ${rangeDays} days`:'All time'}</p><div class="stats">${stat(logs.length,'Workouts')}${stat(a.length,'Completed sets')}${stat(minutes(sum(logs,workSeconds)),'Timed work')}${stat(fmt(displayWeight(sum(logs,volume)))+' '+units(),'Logged rep volume')}</div><h2>Training distribution</h2><table class="report-table"><thead><tr><th>Primary muscle</th><th>Sets in selected range</th><th>Last 7 days / goal</th></tr></thead><tbody>${REGIONS.map(g=>`<tr><td>${esc(g)}</td><td>${a.filter(s=>s.region===g).length}</td><td>${regionSummary(g).sets} / ${regionSummary(g).goal}</td></tr>`).join('')}</tbody></table><h2>Recorded personal bests in range</h2><table class="report-table"><thead><tr><th>Exercise</th><th>Best load</th><th>Best reps</th><th>Longest interval</th></tr></thead><tbody>${[...new Set(a.map(s=>s.exerciseKey))].map(k=>{const s=a.filter(v=>v.exerciseKey===k),best=f=>{const v=s.map(f).filter(x=>x!=null);return v.length?fmt(Math.max(...v)):'—';};return `<tr><td>${esc(s[0].name)}</td><td>${best(x=>x.weight==null?null:displayWeight(x.weight))} ${units()}</td><td>${best(x=>x.reps)}</td><td>${best(x=>x.seconds)} s</td></tr>`;}).join('')}</tbody></table><h2>Latest body measurements (all time)</h2><table class="report-table"><tbody>${BODY_KINDS.map(k=>{const m=latestMeasure(k);return m?`<tr><td>${esc(k)}</td><td>${fmt(m.value)} ${esc(m.unit)}</td><td>${fmtDate(m.date)}</td></tr>`:'';}).join('')}<tr><td>Waist / hip</td><td colspan="2">${r.waistHip.at(-1)?.value.toFixed(2)||'—'}</td></tr><tr><td>Shoulder / waist</td><td colspan="2">${r.shoulderWaist.at(-1)?.value.toFixed(2)||'—'}</td></tr></tbody></table><h2>Session log</h2><table class="report-table"><thead><tr><th>Date</th><th>Routine</th><th>Completed sets</th><th>Minutes</th></tr></thead><tbody>${logs.map(w=>`<tr><td>${fmtDate(w.date)}</td><td>${esc(w.name)}</td><td>${completed(w).length}</td><td>${w.duration==null?'—':fmt(w.duration)}</td></tr>`).join('')}</tbody></table><p class="muted">Unknown loads and reps are excluded from volume. Recovery estimates are elapsed-time heuristics, not medical measurements. Photos are not included.</p></article>`;}
// Optional, explicit cloud snapshot sync. No credentials or access token in the backup.
// Never use a service_role/secret key. The SQL file enables per-user RLS.
try{cloudConfig=JSON.parse(localStorage.getItem('fitlog-cloud-config')||'null');}catch{}
function cloudPanel(){return `<section class="panel"><div class="row spread"><h2>Optional cloud sync</h2><span class="tag">Supabase</span></div><p>Local-only by default. Connect a Supabase project you control to manually push/pull workout and measurement snapshots across devices. Photos remain local. This is manual snapshot synchronization, not automatic merging. Sign-in tokens stay in memory and expire; re-sign in if needed.</p><form id="cloudForm"><label>Project URL<input name="url" type="url" placeholder="https://your-project.supabase.co" value="${esc(cloudConfig?.url||'')}" required></label><label>Public publishable or legacy anon key<input name="key" type="password" autocomplete="off" value="${esc(cloudConfig?.key||'')}" required></label><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary" type="submit" ${cloudBusy?'disabled':''}>Sign in</button></form>${cloudSession?`<p class="coach">Signed in. Cloud revision: ${cloudRevision==null?'not loaded':esc(cloudRevision)}</p><div class="row">${proBtn('cloudPush','Push local snapshot',cloudBusy?'disabled':'')}${proBtn('cloudPull','Pull cloud snapshot',cloudBusy?'disabled':'')}${proBtn('cloudSignout','Sign out')}</div>`:''}<p class="muted">Setup: run included <code>supabase.sql</code>, create a confirmed user, and enter the project's public key here. Never enter an admin/service-role key. Pull replaces local logs after confirmation; push uses revision checks to avoid overwriting unexpected cloud changes.</p>${proBtn('cloudForget','Forget cloud configuration')}</section>`;}
function validCloudConfig(url,key){const u=new URL(url);if(u.protocol!=='https:'||!/^([a-z0-9-]+)\.supabase\.co$/.test(u.hostname)||u.pathname!=='/'||u.search||u.hash||u.username||u.password)throw Error('Use your HTTPS *.supabase.co project URL.');let k=key.trim();if(k.startsWith('sb_secret_'))throw Error('Use a public key, never a secret key.');if(!k.startsWith('sb_publishable_')){try{const p=JSON.parse(atob(k.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(p.role!=='anon')throw Error();}catch{throw Error('Enter a publishable or legacy anon key, never a service-role key.');}}return {url:u.origin,key:k};}
async function cloudFetch(path,opts={},authorized=true){if(!cloudConfig)throw Error('Configure a project first.');const h={apikey:cloudConfig.key,'Content-Type':'application/json',...(opts.headers||{})};if(authorized){if(!cloudSession||Date.now()>=cloudSession.expires)throw Error('Session expired. Sign in again.');h.Authorization='Bearer '+cloudSession.token;}const r=await fetch(cloudConfig.url+path,{...opts,headers:h});const body=await r.text();let data;try{data=body?JSON.parse(body):null;}catch{data=null;}if(!r.ok)throw Error(data?.message||data?.error_description||data?.msg||`Cloud request failed (${r.status})`);return data;}
function rememberCloudRevision(){if(!cloudSession||!cloudConfig)return;try{localStorage.setItem('fitlog-cloud-revision',JSON.stringify({url:cloudConfig.url,userId:cloudSession.userId,revision:cloudRevision}));}catch{}}
async function cloudLogin(f){cloudConfig=validCloudConfig(f.get('url'),f.get('key'));cloudSession=null;cloudRevision=null;const d=await cloudFetch('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})},false);if(!d?.access_token||!d.user?.id)throw Error('Sign-in did not return a valid session.');cloudSession={token:d.access_token,userId:d.user.id,expires:Date.now()+Math.max(1,Number(d.expires_in)||3600)*1000};try{localStorage.setItem('fitlog-cloud-config',JSON.stringify(cloudConfig));}catch{}const row=await cloudRead();let known=null;try{known=JSON.parse(localStorage.getItem('fitlog-cloud-revision')||'null');}catch{}cloudRevision=known?.url===cloudConfig.url&&known?.userId===cloudSession.userId?known.revision:null;toast(row&&cloudRevision!==row.revision?'Signed in. Cloud changed or is new to this device; pull before pushing.':'Cloud sign-in successful');}
async function cloudRead(){const rows=await cloudFetch('/rest/v1/fitlog_snapshots?user_id=eq.'+encodeURIComponent(cloudSession.userId)+'&select=revision,payload,updated_at');if(!Array.isArray(rows))throw Error('Unexpected cloud response.');return rows[0]||null;}
async function cloudPush(){const row=await cloudRead(),revision=row?.revision??null;if(revision!==cloudRevision)throw Error('Cloud changed since your last sync. Export a local backup, pull first, and reconcile changes.');if(!confirm('Push current local workouts, routines, settings and measurements to your private cloud account? Progress photos are excluded.'))return;const payload=clone(state);delete payload.photoBackup;payload.pro.guide=null;payload.pro.restTimer=null;let out;if(row){out=await cloudFetch('/rest/v1/fitlog_snapshots?user_id=eq.'+encodeURIComponent(cloudSession.userId)+'&revision=eq.'+revision,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({payload,revision:revision+1,updated_at:new Date().toISOString()})});}else{out=await cloudFetch('/rest/v1/fitlog_snapshots',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({user_id:cloudSession.userId,payload,revision:1})});}if(!Array.isArray(out)||out.length!==1)throw Error('Cloud snapshot changed during upload. Pull/reconcile before retrying.');cloudRevision=out[0].revision;rememberCloudRevision();toast('Cloud snapshot saved');}
async function cloudPull(){const row=await cloudRead();if(!row){toast('No cloud snapshot yet. Push from the first device.');return;}if(!validPro(row.payload))throw Error('Invalid cloud snapshot');if(!confirm('Replace local logs, routines, settings and measurements with cloud revision '+row.revision+'? Local photos are kept. Export a backup first if needed.'))return;await restoreData(row.payload,false);cloudRevision=row.revision;rememberCloudRevision();toast('Cloud snapshot restored');}
async function runCloud(fn){if(cloudBusy)return;cloudBusy=true;try{await fn();}catch(e){toast('Cloud: '+e.message);}finally{cloudBusy=false;if(page==='settings')render();}}
settings=function(){return old.settings().replace('Version 1.0 · Local-first · No accounts or paid features.','Version 3.0 · Local-first · Optional cloud account.').replace('Export full backup','Export workout backup')+`<section class="panel"><h2>Extended backups</h2><p>IndexedDB mirror: ${dbReady&&!mirrorError?'available':'unavailable or initializing'}. Export a full backup including progress photos if you want to transfer them. Exported photos are not encrypted.</p>${storageError?'<p class="notice">Original local storage could not be read or written. A database snapshot may be recoverable. Export the current state before making changes.</p>':''}<div class="row">${proBtn('backupPhotos','Export backup + photos','','primary')}${proBtn('recoverMirror','Restore local DB snapshot')}</div></section>`+cloudPanel();};
function renderPro(){document.body.classList.toggle('light',state.settings.theme==='light');document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.nav===page||(b.dataset.nav==='routines'&&['editor','session','guide','library','equipment'].includes(page))||(b.dataset.nav==='progress'&&['goals','report'].includes(page))));const routes={home,routines,editor,session,history,progress:analyticsPage,settings,library:libraryPage,equipment:equipmentPage,goals:goalsPage,guide:guidePage,body:bodyPage,report:reportPage};$('#app').innerHTML=(routes[page]||home)();document.body.classList.toggle('report-mode',page==='report');updateTimer();if(page==='body'&&!photoLoading&&!photoCache.length)refreshPhotos();}
render=renderPro;
// Preserve the v1 actions and extend them with validated identities and persisted timers.
doAction=function(b){const a=b.dataset.action;if(a==='exportJSON')return exportFull(false);if(['finish','discard'].includes(a)&&state.pro.guide){guidePause();}const result=old.doAction(b);if(['toggleTimer','stopTimer'].includes(a))rememberTimer();if(['finish','discard'].includes(a)&&!state.active){state.pro.guide=null;save();}if(['addExercise','removeExercise','addSet','removeSet','complete','markAll'].includes(a)&&page==='session'){state.pro.guide=null;save();}return result;};
const previousSave=save;save=function(){migrate(state);previousSave();};
const previousFieldChange=fieldChange;fieldChange=function(el){previousFieldChange(el);if(el.dataset.field==='e.muscle'){const e=current()?.exercises[Number(el.closest('[data-e]')?.dataset.e)];if(e){e.region=({Shoulders:'Side delts',Back:'Upper back',Core:'Abs'}[e.muscle]||e.muscle);save();}}};
function extraAction(b){const a=b.dataset.pro,id=b.dataset.id,ei=Number(b.closest('[data-e]')?.dataset.e),r=current(),e=r?.exercises[ei];switch(a){case 'library':return openLibrary();case 'libBack':return libBack();case 'libChoose':{const l=libBy(id);const names=state.routines.map((r,i)=>`${i+1}. ${r.name}`).join('\n');const n=prompt('Add '+l[1]+' to which routine? Enter its number:\n'+names,'1');if(n===null)return;const dest=state.routines[Number(n)-1];if(!dest){toast('Choose a valid routine number.');return;}dest.exercises.push(makeLibraryExercise(l));editId=dest.id;page='editor';libTarget=null;save();render();return;}case 'libAdd':{const l=libBy(id),t=libTarget;if(!l||!t)return;const dest=t.page==='editor'?routineBy(t.id):state.active;if(!dest)return;dest.exercises.push(makeLibraryExercise(l));save();libBack();toast('Exercise added');return;}case 'equipment':return nav('equipment');case 'newProfile':{const name=prompt('Equipment profile name','New gym');if(!name?.trim())return;const p={id:uid(),name:name.trim(),equipment:['Bodyweight'],weights:[]};state.pro.profiles.push(p);state.pro.profile=p.id;break;}case 'selectProfile':state.pro.profile=id;break;case 'deleteProfile':if(state.pro.profiles.length>1&&confirm('Delete this equipment profile?')){state.pro.profiles=state.pro.profiles.filter(p=>p.id!==id);if(state.pro.profile===id)state.pro.profile=state.pro.profiles[0].id;}break;case 'duplicateRoutine':{if(!r)return;const q=clone(r);q.id=uid();q.name+=' copy';q.exercises.forEach(x=>x.id=uid());state.routines.push(q);editId=q.id;break;}case 'duplicateExercise':if(e){const q=clone(e);q.id=uid();q.sets.forEach(s=>{s.done=false;s.rpe=null;});r.exercises.splice(ei+1,0,q);}break;case 'moveSessionUp':case 'moveSessionDown':{let j=ei+(a==='moveSessionUp'?-1:1);if(r&&j>=0&&j<r.exercises.length)[r.exercises[ei],r.exercises[j]]=[r.exercises[j],r.exercises[ei]];break;}case 'substitute':if(e&&confirm('Replace this exercise and its planned/logged sets? The original exercise remains in past saved workouts.')){const l=libBy(id);if(l){const q=makeLibraryExercise(l);q.rest=e.rest;q.sets=Array.from({length:Math.max(1,e.sets.length)},()=>clone(q.sets[0]));r.exercises[ei]=q;}}break;case 'goals':return nav('goals');case 'backProgress':return nav('progress');case 'readiness':{nav('home');$('#readinessForm')?.scrollIntoView({behavior:'smooth',block:'center'});return;}case 'startGuide':start(id);if(state.active?.routineId===id&&!state.active.editing&&!state.active.past){stopTimer();nav('guide');}return;case 'guided':if(state.active&&!state.active.editing&&!state.active.past){stopTimer();nav('guide');}return;case 'review':return nav('session');case 'guideStart':return guideStart();case 'guidePause':guidePause();return refreshGuide();case 'guideComplete':{const g=state.pro.guide,x=currentGuideItem();if(g?.phase==='work'&&x){const elapsed=Math.max(0,(g.planned||x.s.seconds||0)-guideRemaining(g));if(elapsed===0){toast('Start or skip this interval first.');return;}g.planned=elapsed;}return markGuide();}case 'guideNext':return advanceGuide();case 'guideSkip':return guideSkip();case 'loadVideo':case 'seekVideo':return loadVideo();case 'report':return nav('report');case 'print':return window.print();case 'backupPhotos':return exportFull(true);case 'recoverMirror':return (async()=>{try{const x=await dbOp('state','readonly',o=>o.get('latest'));if(!x||!validPro(x))throw Error('No valid snapshot');if(confirm('Replace current workouts with the most recent local database snapshot?')){await restoreData(x,false);toast('Local snapshot restored');}}catch(e){toast(e.message);}})();case 'deletePhoto':return (async()=>{if(!confirm('Delete this progress photo?'))return;try{await dbOp('photos','readwrite',o=>o.delete(id));await refreshPhotos();toast('Photo deleted');}catch(e){toast(e.message);}})();case 'photoCompare':{const p=photoCache.filter(x=>photoView==='All'||x.view===photoView).sort((a,b)=>a.date.localeCompare(b.date));if(photoView==='All'){toast('Select Front, Side or Back to compare the same view.');return;}if(p.length<2){toast('Add at least two photos of this view.');return;}$('#photoCompare').innerHTML=`<div class="photo-grid compare">${[p[0],p.at(-1)].map(x=>`<div><img src="${esc(x.url)}" alt="${esc(x.view)} comparison"><small>${fmtDate(x.date)}</small></div>`).join('')}</div>`;return;}case 'editMeasurement':{const m=state.measurements.find(m=>m.id===id);if(!m)return;const s=prompt('Correct '+m.kind+' ('+m.unit+')',String(m.value));if(s===null)return;const v=Number(s);if(!Number.isFinite(v)||v<=0||(m.kind==='Body fat'&&v>100)){toast('Enter a valid measurement.');return;}m.value=v;break;}case 'cloudPush':return runCloud(cloudPush);case 'cloudPull':return runCloud(cloudPull);case 'cloudSignout':cloudSession=null;cloudRevision=null;return render();case 'cloudForget':cloudSession=null;cloudRevision=null;cloudConfig=null;try{localStorage.removeItem('fitlog-cloud-config');localStorage.removeItem('fitlog-cloud-revision');}catch{}return render();default:return;}save();render();}
document.addEventListener('click',ev=>{const m=ev.target.closest('[data-muscle]');if(m){selectedRegion=m.dataset.muscle;render();return;}const b=ev.target.closest('[data-pro]');if(b&&!b.disabled)extraAction(b);});
document.addEventListener('keydown',ev=>{const m=ev.target.closest('[data-muscle]');if(m&&['Enter',' '].includes(ev.key)){ev.preventDefault();selectedRegion=m.dataset.muscle;render();}});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='libSearch'){libSearch=el.value;$('#libraryResults').innerHTML=libResults();}if(el.dataset.guide){const s=currentGuideItem()?.s;if(s){s[el.dataset.guide]=el.dataset.guide==='weight'?storeWeight(el.value):num(el.value);save();}}});
document.addEventListener('change',ev=>{const el=ev.target;let redraw=true;switch(el.id){case 'libRegion':libRegion=el.value;$('#libraryResults').innerHTML=libResults();return;case 'libEquipment':libEquipment=el.value;$('#libraryResults').innerHTML=libResults();return;case 'rangeDays':rangeDays=Number(el.value);break;case 'analyticsKey':analyticsKey=el.value;break;case 'analyticsMetric':analyticsMetric=el.value;break;case 'regionPick':selectedRegion=el.value;break;case 'bodyMetric':bodyMetric=el.value;break;case 'bodyKind':$('#bodyUnit').innerHTML=options(bodyUnits(el.value),bodyUnits(el.value)[0]);return;case 'photoView':photoView=el.value;$('#photoGallery').innerHTML=photoMarkup();return;default:redraw=false;}if(redraw)return render();if(el.dataset.goal){state.pro.goals[el.dataset.goal]=Math.min(50,Math.max(0,Math.round(Number(el.value)||0)));save();return render();}if(el.dataset.extra){const e=current()?.exercises[Number(el.closest('[data-e]')?.dataset.e)];if(e){e[el.dataset.extra]=el.value;save();}return;}if(el.dataset.guide){const s=currentGuideItem()?.s;if(s){s[el.dataset.guide]=el.dataset.guide==='weight'?storeWeight(el.value):num(el.value);save();}return;}if(el.dataset.pfield){const p=state.pro.profiles.find(p=>p.id===el.closest('[data-profile]')?.dataset.profile);if(!p)return;const k=el.dataset.pfield;if(k==='equipment'){p.equipment=el.checked?[...new Set([...p.equipment,el.value])]:p.equipment.filter(v=>v!==el.value);}else if(k==='weights'){const raw=el.value.split(',').map(v=>v.trim()).filter(Boolean);if(raw.some(v=>!Number.isFinite(Number(v))||Number(v)<=0)){toast('Use comma-separated positive weights.');return;}p.weights=[...new Set(raw.map(storeWeight))].sort((a,b)=>a-b);}else p.name=el.value.trim()||'Unnamed profile';save();render();}});
document.addEventListener('submit',async ev=>{const form=ev.target;if(!['readinessForm','bodyForm','photoForm','cloudForm'].includes(form.id))return;ev.preventDefault();const f=new FormData(form);try{if(form.id==='readinessForm'){const d={date:dateLocal()};for(const k of ['sleep','energy','soreness','stress'])d[k]=Number(f.get(k));state.pro.readiness=state.pro.readiness.filter(r=>r.date!==d.date);state.pro.readiness.push(d);state.pro.recoveryHours=Math.min(120,Math.max(12,Number(f.get('hours'))||48));save();render();toast('Readiness check-in saved');}else if(form.id==='bodyForm'){const kind=f.get('kind'),value=Number(f.get('value')),unit=f.get('unit');if(!BODY_KINDS.includes(kind)||!bodyUnits(kind).includes(unit)||!Number.isFinite(value)||value<=0||(kind==='Body fat'&&value>100))throw Error('Enter a valid measurement');state.measurements.push({id:uid(),date:f.get('date'),kind,unit,value});bodyMetric=kind;save();render();toast('Measurement saved');}else if(form.id==='photoForm'){const b=form.querySelector('button');b.disabled=true;try{const blob=await compressPhoto(f.get('photo'));await dbOp('photos','readwrite',o=>o.put({id:uid(),date:f.get('date'),view:f.get('view'),blob}));form.reset();await refreshPhotos();toast('Photo stored on this device');}finally{b.disabled=false;}}else{form.querySelector('button').disabled=true;await runCloud(()=>cloudLogin(f));}}catch(e){toast(e.message);}});
render();
function stableLastFor(e){for(const w of ordered()){if(w.id===state.active?.id)continue;const match=w.exercises.find(x=>x.exerciseKey&&x.exerciseKey===e.exerciseKey||!x.exerciseKey&&normalName(x.name)===normalName(e.name));const sets=match?.sets.filter(s=>s.done);if(sets?.length)return sets;}return [];}
